//! # Responsibility
//!
//! This module exposes the skill package assets the build embedded: the router
//! file and one reference file per tool group.
//!
//! ## Owns
//! - The embedded `SKILL_ASSETS` table, generated by the build script
//! - The reference half of that table, in catalog order
//!
//! ## Does not own
//! - The asset names (see `skill_asset_names`)
//! - Which assets are expected (see `clio_types::GROUP_TABLE`)
//!
//! ## Boundary
//!
//! Changes to the assets themselves belong in `skills/clio-mcp`. Changes to how
//! they are embedded belong in `build.rs`.
//!
//! Keep this module focused on handing the embedded text to its readers.

include!(concat!(env!("OUT_DIR"), "/skill_assets.rs"));

/// The reference assets, one per group in catalog order: the asset name and its
/// text. The router file is not among them; read it from `SKILL_ASSETS` first.
#[must_use]
pub fn references() -> &'static [(&'static str, &'static str)] {
    &SKILL_ASSETS[1..]
}

